	@Test
	void retainedTemplateOwnsAnImmutableCopyOfBindingRows() {
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(8, 1, 1024 * 1024L);
		LmdbPipelinePlanCache.Context context = context(17L);
		MapBindingSet originalRow = new MapBindingSet();
		originalRow.addBinding("value", VF.createIRI("urn:original"));
		List<BindingSet> mutableRows = new ArrayList<>();
		mutableRows.add(originalRow);
		QueryRoot coldSource = valuesQuery(mutableRows);

		cache.getOrCompute(coldSource, context, context::revision, () -> {
			coldSource.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
			return coldSource;
		});
		mutableRows.clear();

		MapBindingSet equivalentRow = new MapBindingSet();
		equivalentRow.addBinding("value", VF.createIRI("urn:original"));
		QueryRoot hotSource = valuesQuery(List.of(equivalentRow));
		LmdbPipelinePlanCache.Result hot = cache.getOrCompute(hotSource, context, context::revision, () -> hotSource);
		BindingSetAssignment installed = (BindingSetAssignment) ((QueryRoot) hot.plan()).getArg();
		List<BindingSet> retainedRows = new ArrayList<>();
		installed.getBindingSets().forEach(retainedRows::add);

		assertTrue(hot.cacheHit());
		assertEquals(1, retainedRows.size());
		assertEquals(VF.createIRI("urn:original"), retainedRows.get(0).getValue("value"));
	}

	@Test
	void concurrentEquivalentRequestsShareOneCompletePlanComputation() throws Exception {
		LmdbPipelinePlanCache cache = new LmdbPipelinePlanCache(8, 1, 1024 * 1024L);
		LmdbPipelinePlanCache.Context context = context(17L);
		AtomicInteger computations = new AtomicInteger();
		CountDownLatch ownerEntered = new CountDownLatch(1);
		CountDownLatch releaseOwner = new CountDownLatch(1);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		try {
			QueryRoot firstSource = query("_anon_1", "urn:left");
			Future<LmdbPipelinePlanCache.Result> first = executor.submit(() -> cache.getOrCompute(
					firstSource, context, context::revision, () -> {
						computations.incrementAndGet();
						ownerEntered.countDown();
						await(releaseOwner);
						firstSource.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
						return firstSource;
					}));
			assertTrue(
					ownerEntered.await(Duration.ofSeconds(5).toMillis(), java.util.concurrent.TimeUnit.MILLISECONDS));

			QueryRoot secondSource = query("_anon_2", "urn:left");
			Future<LmdbPipelinePlanCache.Result> second = executor.submit(() -> cache.getOrCompute(
					secondSource, context, context::revision, () -> planned(secondSource, computations)));
			long deadline = System.nanoTime() + Duration.ofSeconds(5).toNanos();
			while (cache.waits() == 0L && System.nanoTime() < deadline) {
				Thread.onSpinWait();
			}
			assertEquals(1L, cache.waits());
			releaseOwner.countDown();

			assertFalse(first.get().cacheHit());
			assertTrue(second.get().cacheHit());
			assertEquals(1, computations.get());
		} finally {
			releaseOwner.countDown();
			executor.shutdownNow();
		}
	}

	private static QueryRoot query(String anonymousName, String predicate) {
		StatementPattern pattern = new StatementPattern(
				Var.of(anonymousName, true), Var.of("predicate", VF.createIRI(predicate)), Var.of("object"));
		Projection projection = new Projection(pattern, new ProjectionElemList(new ProjectionElem("object")));
		return new QueryRoot(projection);
	}

	private static TupleExpr planned(TupleExpr plan, AtomicInteger computations) {
		computations.incrementAndGet();
		plan.setStringMetricPlanned(LmdbCascadesOptimizer.APPLIED_METRIC, "true");
		return plan;
	}

	private static QueryRoot valuesQuery(Iterable<BindingSet> rows) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingNames(Set.of("value"));
		assignment.setBindingSets(rows);
		return new QueryRoot(assignment);
	}

	private static void await(CountDownLatch latch) {
		try {
			latch.await();
		} catch (InterruptedException interrupted) {
			Thread.currentThread().interrupt();
			throw new AssertionError("interrupted while coordinating cache flight", interrupted);
		}
	}

	private static LmdbPipelinePlanCache.Context context(long dataRevision) {
		LmdbEstimatorRuntime.PlanningRevisions planning = new LmdbEstimatorRuntime.PlanningRevisions(
				dataRevision, 2L, 3L, 4L);
		return new LmdbPipelinePlanCache.Context(
				new LmdbPipelinePlanCache.Revision(planning, true), false, 0L,
				LmdbPipelinePlanCache.DatasetIdentity.of(null), LmdbPipelinePlanCache.BindingIdentity.of(null), "",
				false, false, false, "STANDARD", false);
	}
